<?php use App\Core\Authorization; use App\Core\Csrf; $canManage=Authorization::allows('inventory.manage'); $canIssue=Authorization::allows('inventory.issue'); ?>
<div class="inventory-page">
<div class="page-heading"><div><p class="eyebrow">School supplies</p><h1>Uniform &amp; ID inventory</h1><p>Track stock and assignments for students, teachers, and employees.</p></div><div class="hero-actions inventory-actions"><?php if($canIssue):?><a class="button" href="<?=e(url('/uniform-id/issue'))?>">Issue item</a><?php endif;?><?php if($canManage):?><a class="button primary" href="<?=e(url('/uniform-id/create'))?>">Add inventory item</a><?php endif;?></div></div>
<div class="grid four inventory-summary"><article class="stat-card"><span>Inventory items</span><strong><?=(int)($summary['item_count']??0)?></strong><small>All tracked stock variants</small></article><article class="stat-card"><span>Units available</span><strong><?=(int)($summary['units_available']??0)?></strong><small>Current stock balance</small></article><article class="stat-card"><span>Currently issued</span><strong><?=(int)($summary['issued_count']??0)?></strong><small>Not yet returned</small></article><article class="stat-card <?=$summary['low_stock_count']?'stock-warning':''?>"><span>Low stock</span><strong><?=(int)($summary['low_stock_count']??0)?></strong><small>At or below reorder level</small></article></div>
<form method="get" class="inventory-filter" aria-label="Filter inventory"><label class="filter-field">Search<input name="q" value="<?=e($q)?>" placeholder="SKU, item, or size"></label><label class="filter-field">Item type<select name="type"><option value="">All item types</option><option value="uniform" <?=$type==='uniform'?'selected':''?>>Uniforms</option><option value="id_card" <?=$type==='id_card'?'selected':''?>>ID cards</option><option value="other" <?=$type==='other'?'selected':''?>>Other items</option></select></label><button class="button">Filter inventory</button></form>
<section class="card table-card stock-catalog"><div class="table-heading"><h2>Stock catalog</h2></div><table><thead><tr><th scope="col">Item</th><th scope="col">Type</th><th scope="col">Available</th><th scope="col">Issued</th><th scope="col">Reorder level</th><?php if($canManage):?><th scope="col">Stock adjustment</th><?php endif;?></tr></thead><tbody><?php foreach($items as $item):?><?php $typeLabel=['uniform'=>'Uniform','id_card'=>'ID card','other'=>'Other item'][$item['item_type']]??'Other item';?><tr class="<?=$item['is_active']&&$item['quantity_on_hand']<=$item['reorder_level']?'low-stock-row':''?>"><td><strong><?=e($item['name'])?></strong><?php if($item['variant']):?> <span class="badge"><?=e($item['variant'])?></span><?php endif;?><br><small><?=e($item['sku'].' · '.$item['unit'])?></small></td><td><?=e($typeLabel)?></td><td><strong class="stock-number"><?=(int)$item['quantity_on_hand']?></strong></td><td><?=(int)$item['issued_quantity']?></td><td><?=(int)$item['reorder_level']?></td><?php if($canManage):?><td><form class="stock-adjust-form" method="post" action="<?=e(url('/uniform-id/'.$item['id'].'/adjust'))?>"><?=Csrf::field()?><select name="movement_type" aria-label="Adjustment type"><option value="stock_in">Stock received</option><option value="adjustment_in">Correction +</option><option value="adjustment_out">Correction −</option></select><input type="number" min="1" name="quantity" value="1" aria-label="Quantity"><input type="date" name="occurred_on" value="<?=date('Y-m-d')?>" aria-label="Date"><input name="notes" placeholder="Reference / note" aria-label="Notes"><button class="button small">Apply</button></form></td><?php endif;?></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="<?=$canManage?6:5?>" class="empty">No inventory items found. Add the first uniform, ID card, or other stock item.</td></tr><?php endif;?></tbody></table></section>
<section class="card table-card inventory-section"><div class="table-heading"><h2>Issued items</h2><span class="badge"><?=count($issues)?> recent</span></div><table><thead><tr><th scope="col">Recipient</th><th scope="col">Item</th><th scope="col">Issued</th><th scope="col">Outstanding</th><th scope="col">Status</th><?php if($canIssue):?><th scope="col">Return</th><?php endif;?></tr></thead><tbody><?php foreach($issues as $issue):?><?php $outstanding=(int)$issue['quantity']-(int)$issue['returned_quantity'];?><tr><td><strong><?=e($issue['recipient_name'])?></strong><br><small><?=e(ucfirst($issue['recipient_type']).' · '.$issue['reference_no'])?></small></td><td><?=e($issue['item_name'])?><?php if($issue['variant']):?> <span class="badge"><?=e($issue['variant'])?></span><?php endif;?><br><small><?=e($issue['sku'])?></small></td><td><?=(int)$issue['quantity']?><br><small><?=e($issue['issued_on'])?></small></td><td><strong><?=$outstanding?></strong></td><td><span class="badge"><?=e(str_replace('_',' ',$issue['status']))?></span></td><?php if($canIssue):?><td><?php if($outstanding>0):?><form class="return-form" method="post" action="<?=e(url('/uniform-id/issues/'.$issue['id'].'/return'))?>"><?=Csrf::field()?><input type="number" min="1" max="<?=$outstanding?>" name="quantity" value="<?=$outstanding?>" aria-label="Return quantity"><input type="date" name="occurred_on" value="<?=date('Y-m-d')?>" aria-label="Return date"><button class="button small">Return</button></form><?php else:?>—<?php endif;?></td><?php endif;?></tr><?php endforeach;?><?php if(!$issues):?><tr><td colspan="<?=$canIssue?6:5?>" class="empty">No items have been issued.</td></tr><?php endif;?></tbody></table></section>
<section class="card table-card inventory-section"><div class="table-heading"><h2>Recent stock movements</h2></div><table><thead><tr><th scope="col">Date</th><th scope="col">Item</th><th scope="col">Movement</th><th scope="col">Quantity</th><th scope="col">Balance after</th><th scope="col">Recorded by</th></tr></thead><tbody><?php foreach($movements as $movement):?><tr><td><?=e($movement['occurred_on'])?></td><td><strong><?=e($movement['item_name'])?></strong><br><small><?=e($movement['sku'])?></small></td><td><?=e(ucwords(str_replace('_',' ',$movement['movement_type'])))?></td><td><?=(int)$movement['quantity']?></td><td><strong><?=(int)$movement['balance_after']?></strong></td><td><?=e($movement['recorder'])?></td></tr><?php endforeach;?><?php if(!$movements):?><tr><td colspan="6" class="empty">No stock movements recorded.</td></tr><?php endif;?></tbody></table></section>
</div>
